INSERT INTO socialapp.t_posts
    (id, content, visibility, author_id, post_type, moderation_status, code_snippet_details, images, created_at, updated_at) VALUES
    (100081, 'Đoạn gom một trang bảng tin trong đúng ba truy vấn — dài nhưng đọc một mạch được. (#1)', 'PUBLIC', 9458, 'CODE_SNIPPET', 'APPROVED', '{"language":"java","code":"@Service\n@RequiredArgsConstructor\npublic class FeedAssembler {\n\n  private final PostRepository postRepository;\n  private final ReactionRepository reactionRepository;\n  private final CommentRepository commentRepository;\n\n  /**\n   * Gom một trang bảng tin trong đúng ba truy vấn, thay vì một truy vấn cho mỗi bài.\n   */\n  @Transactional(readOnly = true)\n  public List<FeedItem> assemble(List<Long> postIds, Integer viewerId) {\n    if (postIds.isEmpty()) {\n      return List.of();\n    }\n\n    Map<Long, PostEntity> posts = postRepository.findAllByIdIn(postIds).stream()\n        .collect(Collectors.toMap(PostEntity::getId, Function.identity()));\n\n    Map<Long, Long> reactionCounts = reactionRepository.countByPostIdIn(postIds).stream()\n        .collect(Collectors.toMap(CountRow::postId, CountRow::total));\n\n    Map<Long, Long> commentCounts = commentRepository.countRootByPostIdIn(postIds).stream()\n        .collect(Collectors.toMap(CountRow::postId, CountRow::total));\n\n    return postIds.stream()\n        .map(posts::get)\n        .filter(Objects::nonNull)\n        .map(post -> new FeedItem(\n            post,\n            reactionCounts.getOrDefault(post.getId(), 0L),\n            commentCounts.getOrDefault(post.getId(), 0L)))\n        .toList();\n  }\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100082, 'Truy vấn thống kê hồ sơ; cố ý để một dòng rất dài. (#2)', 'PUBLIC', 9323, 'CODE_SNIPPET', 'APPROVED', '{"language":"sql","code":"-- Một dòng dài hơn 120 ký tự, để kiểm nhánh cuộn ngang của khối mã.\nSELECT u.id, u.username, u.full_name, u.elite_score, p.job_title, p.seniority_level, p.years_of_experience, p.primary_role, COUNT(po.id) AS post_count\n  FROM socialapp.t_users u\n  LEFT JOIN socialapp.t_user_professional_profiles p ON p.user_id = u.id\n  LEFT JOIN socialapp.t_posts po ON po.author_id = u.id\n GROUP BY u.id, p.job_title, p.seniority_level, p.years_of_experience, p.primary_role;"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100083, 'Mẩu python mình hay dùng lại, để đây cho ai cần. (#3)', 'PUBLIC', 9437, 'CODE_SNIPPET', 'APPROVED', '{"language":"python","code":"daily = (df.assign(day=df.created_at.dt.floor(\"D\"))\n           .groupby([\"day\", \"source\"], as_index=False)\n           .agg(total=(\"score\", \"sum\")))"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100084, 'Mẩu sql mình hay dùng lại, để đây cho ai cần. (#4)', 'PUBLIC', 9152, 'CODE_SNIPPET', 'APPROVED', '{"language":"sql","code":"CREATE INDEX CONCURRENTLY idx_posts_author_created\n    ON socialapp.t_posts (author_id, created_at DESC);"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100085, 'Mẩu shell mình hay dùng lại, để đây cho ai cần. (#5)', 'PUBLIC', 9015, 'CODE_SNIPPET', 'APPROVED', '{"language":"shell","code":"docker compose down -v\npython scripts/seed/generate_seed.py\ndocker compose up -d"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100086, 'Mẩu json mình hay dùng lại, để đây cho ai cần. (#6)', 'PUBLIC', 9061, 'CODE_SNIPPET', 'APPROVED', '{"language":"json","code":"{\n  \"minioUrl\": \"http://localhost:9000\",\n  \"buckets\": [\"books\", \"book-covers\", \"post-media\"]\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100087, 'Mẩu css mình hay dùng lại, để đây cho ai cần. (#7)', 'PUBLIC', 9295, 'CODE_SNIPPET', 'APPROVED', '{"language":"css","code":".feed-card {\n  container-type: inline-size;\n}\n@container (min-width: 480px) {\n  .feed-card__body { display: grid; grid-template-columns: 1fr auto; }\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100088, 'Mẩu plaintext mình hay dùng lại, để đây cho ai cần. (#8)', 'PUBLIC', 9326, 'CODE_SNIPPET', 'APPROVED', '{"language":"plaintext","code":"statement_timeout = 15s            <- tran cua pool Hikari\nSET LOCAL statement_timeout = 0    <- trong giao dich cua migration"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100089, 'Mẩu kotlin mình hay dùng lại, để đây cho ai cần. (#9)', 'PUBLIC', 9010, 'CODE_SNIPPET', 'APPROVED', '{"language":"kotlin","code":"val feed = repo.observeFeed()\n    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100090, 'Mẩu yaml mình hay dùng lại, để đây cho ai cần. (#10)', 'PUBLIC', 9262, 'CODE_SNIPPET', 'APPROVED', '{"language":"yaml","code":"healthcheck:\n  test: [\"CMD\", \"mc\", \"ready\", \"local\"]\n  interval: 5s\n  retries: 20"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100091, 'Mẩu go mình hay dùng lại, để đây cho ai cần. (#11)', 'PUBLIC', 9085, 'CODE_SNIPPET', 'APPROVED', '{"language":"go","code":"func (s *Server) handleFeed(w http.ResponseWriter, r *http.Request) {\n\tctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)\n\tdefer cancel()\n\ts.render(ctx, w)\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100092, 'Mẩu rust mình hay dùng lại, để đây cho ai cần. (#12)', 'PUBLIC', 9105, 'CODE_SNIPPET', 'APPROVED', '{"language":"rust","code":"let mut seen = HashSet::new();\nposts.retain(|p| seen.insert(p.id));"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100093, 'Mẩu hcl mình hay dùng lại, để đây cho ai cần. (#13)', 'PUBLIC', 9122, 'CODE_SNIPPET', 'APPROVED', '{"language":"hcl","code":"resource \"aws_s3_bucket_versioning\" \"this\" {\n  bucket = aws_s3_bucket.this.id\n  versioning_configuration { status = \"Enabled\" }\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100094, 'Mẩu graphql mình hay dùng lại, để đây cho ai cần. (#14)', 'PUBLIC', 9275, 'CODE_SNIPPET', 'APPROVED', '{"language":"graphql","code":"query {\n  user(login: \"octocat\") {\n    pinnedItems(first: 6) { nodes { ... on Repository { name } } }\n  }\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100095, 'Mẩu zig mình hay dùng lại, để đây cho ai cần. (#15)', 'PUBLIC', 9487, 'CODE_SNIPPET', 'APPROVED', '{"language":"zig","code":"const std = @import(\"std\");\npub fn main() !void {\n    std.debug.print(\"seed\", .{});\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100096, 'Mẩu java mình hay dùng lại, để đây cho ai cần. (#16)', 'PUBLIC', 9011, 'CODE_SNIPPET', 'APPROVED', '{"language":"java","code":"var stats = sessionFactory.getStatistics();\nstats.setStatisticsEnabled(true);\nservice.loadFeed(userId);\nassertThat(stats.getPrepareStatementCount()).isLessThan(5);"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100097, 'Mẩu typescript mình hay dùng lại, để đây cho ai cần. (#17)', 'PUBLIC', 9373, 'CODE_SNIPPET', 'APPROVED', '{"language":"typescript","code":"export function useDebounced<T>(value: T, delay = 300): T {\n  const [v, setV] = useState(value);\n  useEffect(() => {\n    const id = setTimeout(() => setV(value), delay);\n    return () => clearTimeout(id);\n  }, [value, delay]);\n  return v;\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
