    (100227, 'Mẩu rust mình hay dùng lại, để đây cho ai cần. (#147)', 'PUBLIC', 9400, 'CODE_SNIPPET', 'APPROVED', '{"language":"rust","code":"let mut seen = HashSet::new();\nposts.retain(|p| seen.insert(p.id));"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100228, 'Mẩu hcl mình hay dùng lại, để đây cho ai cần. (#148)', 'PUBLIC', 9173, 'CODE_SNIPPET', 'APPROVED', '{"language":"hcl","code":"resource \"aws_s3_bucket_versioning\" \"this\" {\n  bucket = aws_s3_bucket.this.id\n  versioning_configuration { status = \"Enabled\" }\n}"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100229, 'Mẩu graphql mình hay dùng lại, để đây cho ai cần. (#149)', 'PUBLIC', 9011, 'CODE_SNIPPET', 'APPROVED', '{"language":"graphql","code":"query {\n  user(login: \"octocat\") {\n    pinnedItems(first: 6) { nodes { ... on Repository { name } } }\n  }\n}"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100230, 'Mẩu zig mình hay dùng lại, để đây cho ai cần. (#150)', 'PUBLIC', 9269, 'CODE_SNIPPET', 'APPROVED', '{"language":"zig","code":"const std = @import(\"std\");\npub fn main() !void {\n    std.debug.print(\"seed\", .{});\n}"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100231, 'Mẩu java mình hay dùng lại, để đây cho ai cần. (#151)', 'PUBLIC', 9001, 'CODE_SNIPPET', 'APPROVED', '{"language":"java","code":"var stats = sessionFactory.getStatistics();\nstats.setStatisticsEnabled(true);\nservice.loadFeed(userId);\nassertThat(stats.getPrepareStatementCount()).isLessThan(5);"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100232, 'Mẩu typescript mình hay dùng lại, để đây cho ai cần. (#152)', 'PUBLIC', 9416, 'CODE_SNIPPET', 'APPROVED', '{"language":"typescript","code":"export function useDebounced<T>(value: T, delay = 300): T {\n  const [v, setV] = useState(value);\n  useEffect(() => {\n    const id = setTimeout(() => setV(value), delay);\n    return () => clearTimeout(id);\n  }, [value, delay]);\n  return v;\n}"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100233, 'Mẩu python mình hay dùng lại, để đây cho ai cần. (#153)', 'PUBLIC', 9131, 'CODE_SNIPPET', 'APPROVED', '{"language":"python","code":"daily = (df.assign(day=df.created_at.dt.floor(\"D\"))\n           .groupby([\"day\", \"source\"], as_index=False)\n           .agg(total=(\"score\", \"sum\")))"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100234, 'Mẩu sql mình hay dùng lại, để đây cho ai cần. (#154)', 'PUBLIC', 9192, 'CODE_SNIPPET', 'APPROVED', '{"language":"sql","code":"CREATE INDEX CONCURRENTLY idx_posts_author_created\n    ON socialapp.t_posts (author_id, created_at DESC);"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100235, 'Mẩu shell mình hay dùng lại, để đây cho ai cần. (#155)', 'PUBLIC', 9377, 'CODE_SNIPPET', 'APPROVED', '{"language":"shell","code":"docker compose down -v\npython scripts/seed/generate_seed.py\ndocker compose up -d"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100236, 'Mẩu json mình hay dùng lại, để đây cho ai cần. (#156)', 'PUBLIC', 9234, 'CODE_SNIPPET', 'APPROVED', '{"language":"json","code":"{\n  \"minioUrl\": \"http://localhost:9000\",\n  \"buckets\": [\"books\", \"book-covers\", \"post-media\"]\n}"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100237, 'Mẩu css mình hay dùng lại, để đây cho ai cần. (#157)', 'PUBLIC', 9194, 'CODE_SNIPPET', 'APPROVED', '{"language":"css","code":".feed-card {\n  container-type: inline-size;\n}\n@container (min-width: 480px) {\n  .feed-card__body { display: grid; grid-template-columns: 1fr auto; }\n}"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100238, 'Mẩu plaintext mình hay dùng lại, để đây cho ai cần. (#158)', 'PUBLIC', 9244, 'CODE_SNIPPET', 'APPROVED', '{"language":"plaintext","code":"statement_timeout = 15s            <- tran cua pool Hikari\nSET LOCAL statement_timeout = 0    <- trong giao dich cua migration"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100239, 'Mẩu kotlin mình hay dùng lại, để đây cho ai cần. (#159)', 'PUBLIC', 9336, 'CODE_SNIPPET', 'APPROVED', '{"language":"kotlin","code":"val feed = repo.observeFeed()\n    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100240, 'Mẩu yaml mình hay dùng lại, để đây cho ai cần. (#160)', 'PUBLIC', 9264, 'CODE_SNIPPET', 'APPROVED', '{"language":"yaml","code":"healthcheck:\n  test: [\"CMD\", \"mc\", \"ready\", \"local\"]\n  interval: 5s\n  retries: 20"}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days');
