INSERT INTO socialapp.t_posts
    (id, content, visibility, author_id, post_type, moderation_status, images, created_at, updated_at) VALUES
    (100841, 'Ghi lại sau một tuần vật lộn: tối ưu truy vấn N+1. Con số cụ thể: từ 2.4s xuống 900ms, đo trên môi trường thật chứ không phải máy cá nhân. (#1)', 'PUBLIC', 9298, 'REGULAR', 'APPROVED', '["${minioUrl}/post-media/posts/100841/img1.png"]'::jsonb, now() - INTERVAL '57 days', now() - INTERVAL '57 days'),
    (100842, 'Ghi lại sau một tuần vật lộn: chọn TTL cho cache. Con số cụ thể: từ 180ms xuống một buổi chiều, đo trên môi trường thật chứ không phải máy cá nhân. (#2)', 'PUBLIC', 9316, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '57 days', now() - INTERVAL '57 days'),
    (100843, 'Ghi lại sau một tuần vật lộn: đánh index đúng thứ tự cột. Con số cụ thể: từ 45 phút xuống 8 phút, đo trên môi trường thật chứ không phải máy cá nhân. (#3)', 'PUBLIC', 9132, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '57 days', now() - INTERVAL '57 days'),
    (100844, 'Ghi lại sau một tuần vật lộn: chuyển sang virtual threads. Con số cụ thể: từ 3 giờ xuống 20 nghìn hàng, đo trên môi trường thật chứ không phải máy cá nhân. (#4)', 'PUBLIC', 9383, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '57 days', now() - INTERVAL '57 days'),
    (100845, 'Ghi lại sau một tuần vật lộn: tách monolith thành service. Con số cụ thể: từ 12 giây xuống 45 phút, đo trên môi trường thật chứ không phải máy cá nhân. (#5)', 'PUBLIC', 9015, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '57 days', now() - INTERVAL '57 days'),
    (100846, 'Ghi lại sau một tuần vật lộn: thiết kế API phân trang. Con số cụ thể: từ 900ms xuống 900ms, đo trên môi trường thật chứ không phải máy cá nhân. (#6)', 'PUBLIC', 9334, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100847, 'Ghi lại sau một tuần vật lộn: xử lý idempotency cho webhook. Con số cụ thể: từ 1.2s xuống một buổi chiều, đo trên môi trường thật chứ không phải máy cá nhân. (#7)', 'PUBLIC', 9001, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100848, 'Ghi lại sau một tuần vật lộn: chuẩn hoá log có traceId. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt 70ms, còn dưới ngưỡng đó thì trông vẫn ổn. (#8)', 'PUBLIC', 9071, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100849, 'Ghi lại sau một tuần vật lộn: đo p99 thay vì trung bình. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt một buổi chiều, còn dưới ngưỡng đó thì trông vẫn ổn. (#9)', 'PUBLIC', 9192, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100850, 'Ghi lại sau một tuần vật lộn: giảm thời gian build CI. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt hai ngày, còn dưới ngưỡng đó thì trông vẫn ổn. (#10)', 'PUBLIC', 9162, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100851, 'Ghi lại sau một tuần vật lộn: viết test không phụ thuộc thứ tự. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt 40%, còn dưới ngưỡng đó thì trông vẫn ổn. (#11)', 'PUBLIC', 9304, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100852, 'Ghi lại sau một tuần vật lộn: mock ít đi, dùng testcontainers. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt 8 phút, còn dưới ngưỡng đó thì trông vẫn ổn. (#12)', 'PUBLIC', 9010, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '58 days', now() - INTERVAL '58 days'),
    (100853, 'Ghi lại sau một tuần vật lộn: dựng design token dùng chung. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt 300MB, còn dưới ngưỡng đó thì trông vẫn ổn. (#13)', 'PUBLIC', 9377, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100854, 'Ghi lại sau một tuần vật lộn: giảm layout shift. Cái bẫy nằm ở chỗ nó chỉ lộ ra khi dữ liệu vượt 1.5GB, còn dưới ngưỡng đó thì trông vẫn ổn. (#14)', 'PUBLIC', 9476, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100855, 'Ghi lại sau một tuần vật lộn: làm form truy cập được bằng bàn phím. Mất 20 nghìn hàng để tìm ra nguyên nhân và 45 phút để sửa — tỉ lệ quen thuộc. (#15)', 'PUBLIC', 9313, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100856, 'Ghi lại sau một tuần vật lộn: chia bundle theo route. Mất 2.4s để tìm ra nguyên nhân và 900ms để sửa — tỉ lệ quen thuộc. (#16)', 'PUBLIC', 9111, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100857, 'Ghi lại sau một tuần vật lộn: quản lý state không cần thư viện. Mất 180ms để tìm ra nguyên nhân và một buổi chiều để sửa — tỉ lệ quen thuộc. (#17)', 'PUBLIC', 9034, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100858, 'Ghi lại sau một tuần vật lộn: đồng bộ dữ liệu khi mất mạng. Mất 45 phút để tìm ra nguyên nhân và 8 phút để sửa — tỉ lệ quen thuộc. (#18)', 'PUBLIC', 9194, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100859, 'Ghi lại sau một tuần vật lộn: giảm kích thước app. Mất 3 giờ để tìm ra nguyên nhân và 20 nghìn hàng để sửa — tỉ lệ quen thuộc. (#19)', 'PUBLIC', 9477, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '59 days', now() - INTERVAL '59 days'),
    (100860, 'Ghi lại sau một tuần vật lộn: bảo mật token trên thiết bị. Mất 12 giây để tìm ra nguyên nhân và 45 phút để sửa — tỉ lệ quen thuộc. (#20)', 'PUBLIC', 9417, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '60 days', now() - INTERVAL '60 days'),
    (100861, 'Ghi lại sau một tuần vật lộn: rà soát phụ thuộc bên thứ ba. Mất 900ms để tìm ra nguyên nhân và 900ms để sửa — tỉ lệ quen thuộc. (#21)', 'PUBLIC', 9254, 'REGULAR', 'APPROVED', NULL, now() - INTERVAL '60 days', now() - INTERVAL '60 days'),
